  "pairing-token": {"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://lantern.boreale.dev/schemas/v1/pairing-token.json","title":"Pairing token","description":"GET poll once the user approved on the server's side (SPEC.md § 5.2). Sent as Authorization: Bearer <token> (§ 5.1).","type":"object","properties":{"schema":{"$ref":"common.json#/$defs/schema1"},"token":{"$ref":"common.json#/$defs/opaque","description":"Opaque, 128 bits of entropy at least."},"scopes":{"type":"array","items":{"$ref":"common.json#/$defs/scope"},"uniqueItems":true},"expires":{"description":"Seconds until the token expires; absent, it lasts until revoked.","type":"integer","minimum":1},"bound":{"type":"boolean","description":"Whether the token is bound to the key sent at pairing (SPEC.md § 5.4)."},"rating_cap":{"$ref":"common.json#/$defs/rating_cap"}},"required":["schema","token","scopes"]},
  "problem": {"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://lantern.boreale.dev/schemas/v1/problem.json","title":"Error","description":"Every error, application/problem+json (RFC 9457; SPEC.md § 12), extended by `schema` and `code`.","type":"object","properties":{"schema":{"$ref":"common.json#/$defs/schema1"},"type":{"$ref":"common.json#/$defs/url"},"title":{"$ref":"common.json#/$defs/name"},"status":{"type":"integer","minimum":400,"maximum":599},"detail":{"$ref":"common.json#/$defs/text"},"code":{"enum":["bad_request","key_required","unauthorized","signature_required","signature_invalid","signature_expired","signature_replayed","forbidden","account_frozen","not_found","conflict","gone","too_large","unsupported_schema","digest_mismatch","slow_down","internal","unavailable"]},"language":{"$ref":"common.json#/$defs/language","description":"The language of title and detail (SPEC.md § 2.2)."}},"required":["schema","status","code"]},
  "request-create": {"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://lantern.boreale.dev/schemas/v1/request-create.json","title":"A request","description":"POST <base>/v1/requests (SPEC.md § 11); platform defaults to the client's.","type":"object","properties":{"schema":{"$ref":"common.json#/$defs/schema1"},"platform":{"$ref":"common.json#/$defs/platform"},"title_id":{"$ref":"common.json#/$defs/id"}},"required":["schema","title_id"]},
  "request": {"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://lantern.boreale.dev/schemas/v1/request.json","title":"A request","description":"POST <base>/v1/requests, answered with 201 or 200 (SPEC.md § 11): the request, as listed.","allOf":[{"$ref":"common.json#/$defs/request"},{"type":"object","properties":{"schema":{"$ref":"common.json#/$defs/schema1"}},"required":["schema"]}]},
